from mk import *

def fig():
    g = Fig(560, 300, "משטח ומאוורר: תיבה במסה 2 קילוגרם בנקודה A על הקרקע. המסילה עולה לקטע אופקי BD באורך 4 מטר בגובה 0.8 מטר. המאוורר בנקודה D מפעיל כוח F שמאלה. וגרף F כפונקציה של x: קו ישר מ-0 ב-B עד 8 ניוטון ב-4 מטר")
    g.path("M 30,140 L 140,140 Q 190,140 210,100 Q 230,70 260,70 L 470,70", width=2.5)
    g.block(70, 128, 26, 20, "m"); g.text(70, 160, "A")
    for x, t in ((260, "B"), (365, "C"), (470, "D")): g.dot(x, 70); g.text(x, 92, t)
    g.dim(260, 108, 470, 108, "4m", offset=0); g.dim(500, 70, 500, 140, "h = 0.8 m", offset=0)
    g.line(30, 140, 520, 140, stroke="var(--d-dim)", width=1, dash="4 3")
    g.circle(480, 46, 10, fill="var(--d-fill)", stroke="var(--d-line)"); g.arrow(460, 40, 420, 40, "F", lx=430, ly=32)
    X, Y = g.graph(200, 280, 200, 100, "x (m)", "F (N)", xticks=[(v, str(v)) for v in (1, 2, 3, 4)], yticks=[(v, str(v)) for v in (2, 4, 6, 8)], xmax=4.3, ymax=8.5)
    g.plot(X, Y, [(0, 0), (4, 8)])
    return g

E(id="bagrut-2019-q4", year=2019, label="2019 שאלה 4", topic="energy", sub="en-work", diff=3, fig=fig,
  stem=r"כדי לחקור את נושא האנרגייה המכנית, תלמיד בנה מערכת ובה תיבה שמסתה $m = 2\,\text{kg}$, משטח $AD$ ומאוורר. הקטע $BD$ של המשטח הוא מישור אופקי שאורכו $4\,\text{m}$, וגובהו מעל הקרקע $h = 0.8\,\text{m}$. החיכוך בין המשטח ובין התיבה ניתן להזנחה. התלמיד הציב את התיבה בנקודה $A$ ואת המאוורר בנקודה $D$. המאוורר הניע את האוויר ויצר רוח אופקית. הנח כי גודל הכוח $F$ שהרוח הפעילה על התיבה תלוי לינארית במרחק $x$ של התיבה מהנקודה $B$, כמתואר בגרף. גודל הכוח הוא מרבי בנקודה $D$ ומתאפס בנקודה $B$. משמאל לנקודה $B$ הרוח אינה משפיעה. בשאלה זו יש להתחשב בהשפעת האוויר מהמאוורר בלבד, ולהזניח כל השפעה אחרת של האוויר.",
  parts=[
    P("א", r"חשב את גודל המהירות המזערית (המינימלית) שיש להעניק לתיבה שנמצאת בנקודה $A$, כדי שתנוע במעלה המשטח ותגיע לנקודה $B$.", num(4, "m/s"), ["principle"], [
        S(r"שימור אנרגיה", r"מגיעה ל-$B$ בדיוק עם מהירות אפס", r"\tfrac{1}{2}v^2 = g h \Rightarrow v = \sqrt{2 \cdot 10 \cdot 0.8} = 4\,\text{m/s}"),
    ], r"$4\,\text{m/s}$", key=r"v=4 m/s"),
    P("ב", r"בנקודה $A$ העניק התלמיד לתיבה מהירות התחלתית $v_0 = 5\,\text{m/s}$ שכיוונה ימינה. כאשר הגיעה התיבה לנקודה $B$ החל להשפיע עליה הכוח $F(x)$. בנקודה $C$ נעצרת התיבה עצירה רגעית. חשב את עבודת הכוח $F(x)$ מהנקודה $B$ עד לנקודה $C$.", num(-9, "J"), ["principle", "signs"], [
        S(r"האנרגיה הקינטית ב-$B$", r"שימור אנרגיה מ-$A$", r"\tfrac{1}{2} \cdot 2 \cdot 5^2 - 2 \cdot 10 \cdot 0.8 = 25 - 16 = 9\,\text{J}"),
        S(r"משפט העבודה והאנרגיה", r"התיבה נעצרת ב-$C$, וב-$BC$ רק $F$ עושה עבודה", r"W_F = 0 - 9 = -9\,\text{J}"),
    ], r"$-9\,\text{J}$", key=r"w=−9 J"),
    P("ג", r"חשב את המרחק של הנקודה $C$ מהנקודה $B$.", num(3, "m"), ["graph", "algebra"], [
        S(r"העבודה היא השטח מתחת לגרף", r"משולש: $F = 2x$", r"|W| = \tfrac{1}{2} x \cdot 2x = x^2"),
        S(r"פותרים", r"השטח שווה ל-9 J", r"x^2 = 9 \Rightarrow x = 3\,\text{m}"),
    ], r"$3\,\text{m}$", key=r"x=3 m"),
    P("ד", r"אחרי העצירה הרגעית בנקודה $C$, התיבה נעה חזרה לכיוון הנקודה $B$. תאר במילים את תנועתה של התיבה מהנקודה $C$ ועד לנקודה $B$. בתשובתך התייחס למאפיינים: תנועה קצובה או מואצת, תאוצה קבועה או משתנה, גודל מהירות קטן או גדל.", OPEN, ["principle"], [
        S(r"הכוח", r"שמאלה, בכיוון התנועה, וקטן ככל שהתיבה מתקרבת ל-$B$", r"F = 2x\ \downarrow"),
        S(r"התנועה", r"מואצת, בתאוצה שקטנה, והמהירות גדלה", r"a = \frac{F}{m}\ \downarrow,\ v\uparrow"),
    ], r"מואצת, בתאוצה הולכת וקטנה, וגודל המהירות גדל", key=r"מואצת, תאוצה קטנה, מהירות גדלה"),
    P("ה", r"קבע את גודל מהירות התיבה בהגיעה חזרה לנקודה $A$. נמק את קביעתך. בתשובתך התייחס גם לכוחות הלא משמרים שקיימים במערכת.", num(5, "m/s"), ["principle"], [
        S(r"הכוח $F(x)$ תלוי רק במקום", r"העבודה שלו בדרך חזרה מבטלת את העבודה בדרך הלוך, ואין חיכוך", r"W_F + W_F' = -9 + 9 = 0"),
        S(r"מסקנה", r"התיבה חוזרת לאותו גובה עם אותה אנרגיה", r"v_A = 5\,\text{m/s}"),
    ], r"$5\,\text{m/s}$", key=r"vA=5 m/s"),
  ],
  concepts=["משפט העבודה והאנרגיה", "כוח משתנה", "שטח מתחת לגרף כוח-מקום", "שימור אנרגיה"],
  summary=r"תיבה שנבלמת ברוח של מאוורר שחזקה יותר ככל שמתקרבים אליו: עבודה כשטח מתחת לגרף, נקודת העצירה, ולמה התיבה חוזרת באותה מהירות.")
